+                attachments: [],
+                annotations: [],
+              },
+            ],
+          },
+        ],
+      },
+    ],
+  };
+}
+
+/** controls 套件的 save-detection.spec.ts + reverse-check.spec.ts 節點。 */
+export function controlsSuites({
