+  controlAResultStatus = 'failed',
+  controlAErrorMessage = '對照 A（舊判定）預期失敗：讀到的應是舊內容而非新內容',
+  controlARetry = 0,
+  controlAExpectedStatus = 'failed',
+  controlBOk = true,
+  reverseCheckSkipped = true,
+} = {}) {
+  const controlATest = {
