+        errors: controlAErrorMessage ? [{ message: controlAErrorMessage }] : [],
+        stdout: [],
+        stderr: [],
+        retry: controlARetry,
+        startTime: '2026-09-28T00:00:00.000Z',
+        attachments: [],
+        annotations: [],
+      },
+    ],
+  };
+  const controlBTest = {
+    timeout: 60000,
+    annotations: [],
+    expectedStatus: 'passed',
+    projectName: '',
+    projectId: '',
+    status: controlBOk ? 'expected' : 'unexpected',
+    results: [
+      {
+        workerIndex: 0,
+        parallelIndex: 0,
+        status: controlBOk ? 'passed' : 'failed',
+        duration: 100,
+        error: undefined,
+        errors: [],
+        stdout: [],
